import { useState, useEffect } from 'react';

export default function QuestionTimer({ timeout, onTimeout }) {

    const [remainingTime, setRemainingTime] = useState(timeout);

    /*
        组件首次渲染和每次timeout或onTimeout变化时，
        都设置一个延时为timeout毫秒的定时器，
        定时器结束时执行onTimeout函数。
        
        这可以用于实现各种功能，比如延迟显示消息、延时调用API等
    */
    useEffect(() => {
        const timer = setTimeout(onTimeout, timeout);


    }, [timeout, onTimeout]); 

    /*
        使用React的useEffect Hook来实现一个定时器，
        该定时器会每隔100毫秒减少一次状态remainingTime的值
    */

    // setInterval和回调函数: 在useEffect的函数体内，使用了setInterval来创建一个定时器，它每100毫秒执行一次传递给它的回调函数。
    // 这个回调函数通过调用setRemainingTime更新状态remainingTime，每次调用都会将remainingTime的值减少100。

    // setRemainingTime函数: setRemainingTime是一个更新状态的函数。
    // 这里，它使用了一个函数式更新，即prevRemainingTime => prevRemainingTime - 100。
    // 这种方式可以确保每次更新都基于前一次的状态值，避免因状态更新的异步性质而出现的问题。

    // 依赖数组: useEffect的第二个参数是一个依赖数组。
    // 在这个例子中，依赖数组为空（[]），这意味着副作用只会在组件首次渲染时执行一次。
    // 因此，定时器只会设置一次，而不会在组件的后续更新中重新设置
    useEffect(() => {

        const interval = setInterval(() => {
            setRemainingTime((prevRemainingTime) => prevRemainingTime - 100);
        }, 100); 

        return () => {
            clearInterval(interval); 
        };
    }, []);

    return <progress id = "question-time" max = {timeout} value = {remainingTime} />; 
}
